CREATE TABLE IF NOT EXISTS "country" (
	"countryID" INTEGER,
	"name" VARCHAR(255) NOT NULL UNIQUE,
	PRIMARY KEY("countryID")
);

CREATE TABLE IF NOT EXISTS "cart" (
	"cartID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"status" VARCHAR(20) NOT NULL DEFAULT 'active' CHECK("status" IN ('active', 'purchased', 'cancelled')),
	"total" NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK("total" >= 0),
	PRIMARY KEY("cartID")
);

CREATE TABLE IF NOT EXISTS "user" (
	"UUID" UUID,
	"username" VARCHAR(255) NOT NULL UNIQUE,
	"password" VARCHAR(255) NOT NULL,
	"countryID" INTEGER NOT NULL,
	"balance" NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK("balance" >= 0),
	"cartID" INTEGER UNIQUE,
	PRIMARY KEY("UUID")
);

CREATE TABLE IF NOT EXISTS "director" (
	"directorID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	PRIMARY KEY("directorID")
);

CREATE TABLE IF NOT EXISTS "actor" (
	"actorID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	PRIMARY KEY("actorID")
);

CREATE TABLE IF NOT EXISTS "film" (
	"filmID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"title" VARCHAR(255) NOT NULL,
	"description" TEXT NOT NULL,
	"directorID" INTEGER,
	"price" NUMERIC(10,2) NOT NULL CHECK("price" >= 0),
	"filmScore" INTEGER NOT NULL DEFAULT 0 CHECK("filmScore" BETWEEN 0 AND 10),
	PRIMARY KEY("filmID")
);

CREATE TABLE IF NOT EXISTS "film_actor" (
	"filmID" INTEGER NOT NULL,
	"actorID" INTEGER NOT NULL,
	PRIMARY KEY("filmID", "actorID")
);

CREATE TABLE IF NOT EXISTS "inventory" (
	"inventoryID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"filmID" INTEGER NOT NULL UNIQUE,
	"amount" INTEGER NOT NULL DEFAULT 0 CHECK("amount" >= 0),
	PRIMARY KEY("inventoryID")
);

CREATE TABLE IF NOT EXISTS "cartLine" (
	"lineID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"inventoryID" INTEGER NOT NULL,
	"cartID" INTEGER NOT NULL,
	"quantity" INTEGER NOT NULL CHECK("quantity" > 0),
	PRIMARY KEY("lineID"),
	CONSTRAINT "inv_to_car_unique_0" UNIQUE ("inventoryID", "cartID")
);

CREATE TABLE IF NOT EXISTS "purchase" (
	"purchaseID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"UUID" UUID NOT NULL,
	"purchaseDate" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"total" NUMERIC(10,2) NOT NULL CHECK("total" >= 0),
	"status" VARCHAR(20) NOT NULL DEFAULT 'completed' CHECK("status" IN ('pending' , 'completed' , 'cancelled')),
	PRIMARY KEY("purchaseID")
);

CREATE TABLE IF NOT EXISTS "purchase_detail" (
	"purchaseID" INTEGER NOT NULL,
	"filmID" INTEGER NOT NULL,
	"quantity" INTEGER NOT NULL CHECK("quantity" > 0),
	"unitPrice" NUMERIC(10,2) NOT NULL CHECK("unitPrice" >= 0),
	PRIMARY KEY("purchaseID", "filmID")
);

CREATE TABLE IF NOT EXISTS "vote" (
	"voteID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"UUID" UUID NOT NULL,
	"filmID" INTEGER NOT NULL,
	"score" SMALLINT NOT NULL CHECK("score" BETWEEN 0 AND 10),
	"voteDate" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("UUID", "filmID")
);

ALTER TABLE "user"
ADD FOREIGN KEY("countryID") REFERENCES "country"("countryID")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "user"
ADD FOREIGN KEY("cartID") REFERENCES "cart"("cartID")
ON UPDATE NO ACTION ON DELETE SET NULL;
ALTER TABLE "film"
ADD FOREIGN KEY("directorID") REFERENCES "director"("directorID")
ON UPDATE NO ACTION ON DELETE SET NULL;
ALTER TABLE "film_actor"
ADD FOREIGN KEY("filmID") REFERENCES "film"("filmID")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "film_actor"
ADD FOREIGN KEY("actorID") REFERENCES "actor"("actorID")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "inventory"
ADD FOREIGN KEY("filmID") REFERENCES "film"("filmID")
ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "cartLine"
ADD FOREIGN KEY("inventoryID") REFERENCES "inventory"("inventoryID")
ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "cartLine"
ADD FOREIGN KEY("cartID") REFERENCES "cart"("cartID")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "purchase"
ADD FOREIGN KEY("UUID") REFERENCES "user"("UUID")
ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "purchase_detail"
ADD FOREIGN KEY("purchaseID") REFERENCES "purchase"("purchaseID")
ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "purchase_detail"
ADD FOREIGN KEY("filmID") REFERENCES "film"("filmID")
ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "vote"
ADD FOREIGN KEY("UUID") REFERENCES "user"("UUID")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "vote"
ADD FOREIGN KEY("filmID") REFERENCES "film"("filmID")
ON UPDATE NO ACTION ON DELETE CASCADE;



CREATE OR REPLACE FUNCTION reservar_stock()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE "inventory"
    SET "amount" = "amount" - NEW."quantity"
    WHERE "inventoryID" = NEW."inventoryID"
    AND "amount" >= NEW."quantity";

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La película no tiene suficiente stock';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER reservar_stock_trigger
BEFORE INSERT ON "cartLine"
FOR EACH ROW
EXECUTE FUNCTION reservar_stock();



CREATE OR REPLACE FUNCTION calcular_total_carrito()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    target_cartID INTEGER;
BEGIN
    IF TG_OP = 'DELETE' THEN
        target_cartID := OLD."cartID";
    ELSE
        target_cartID := NEW."cartID";
    END IF;

    UPDATE "cart" 
    SET "total" = COALESCE((
        SELECT SUM("cartLine"."quantity" * film."price")
        FROM "cartLine"
        JOIN "inventory"
        ON inventory."inventoryID" = "cartLine"."inventoryID"
        JOIN "film"
        ON film."filmID" = inventory."filmID"
        WHERE "cartLine"."cartID" = target_cartID
    ), 0)
    WHERE cart."cartID" = target_cartID;

    RETURN NULL;
END;
$$;

CREATE TRIGGER calcular_total_carrito_trigger
AFTER INSERT OR UPDATE OR DELETE ON "cartLine"
FOR EACH ROW
EXECUTE FUNCTION calcular_total_carrito();




CREATE OR REPLACE FUNCTION cobrar_usuario()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW."status" = 'completed' THEN
        UPDATE "user"
        SET "balance" = "balance" - NEW."total"
        WHERE "UUID" = NEW."UUID"
          AND "balance" >= NEW."total";

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Saldo del usuario insuficiente';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER cobrar_usuario_trigger
BEFORE INSERT ON "purchase"
FOR EACH ROW
EXECUTE FUNCTION cobrar_usuario();





CREATE OR REPLACE PROCEDURE actualizar_puntuacion_media(
    p_filmID INTEGER
)
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE "film"
    SET "filmScore" = COALESCE(
        (
            SELECT ROUND(AVG("score"), 2)
            FROM "vote"
            WHERE "filmID" = p_filmID
        ),
        0
    )
    WHERE "filmID" = p_filmID;
END;
$$;

CREATE OR REPLACE FUNCTION actualizar_puntuacion__trigger()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    CALL actualizar_puntuacion_media(NEW."filmID");

    RETURN NEW;
END;
$$;

CREATE TRIGGER actualizar_puntuacion__trigger
AFTER INSERT ON "vote"
FOR EACH ROW
EXECUTE FUNCTION actualizar_puntuacion__trigger();
